insert into public.trait_places (key, icon, name, position) values ('home','🏠','Home & private life',0),('friends','🧑‍🤝‍🧑','With friends',1),('school','🏫','School',2),('work','💼','Work & teams',3),('online','💻','Online',4) on conflict (key) do update set icon=excluded.icon, name=excluded.name, position=excluded.position;
insert into public.traits (key, icon, name, family, min_age, varies_by_place, low_name, low_self, low_others, mid_name, mid_text, high_name, high_self, high_others, place_note, position) values
('boundaries','🚧','Respecting boundaries','Character',6,true,'Crosses lines','Gets into trouble and loses people''s trust.','Steps into other people''s private space, things and choices.','Knows the line','Knows what is OK and not OK, for himself and for others.','Builds walls','Feels lonely and won''t ask for help.','Won''t share or join in, even when working together is needed.','The line moves with the place: in someone''s private life, give space; in a school project or a team at work, joining in is expected.',0),
('feelings','🎛️','Controlling feelings','Character',6,true,'Explodes','Says and does things he is sorry for later.','Scares or hurts people when angry.','Calm and steady','Feels anger, sadness and joy, and still acts calmly.','Bottles up','Hides feelings until they pile up.','Seems cold: people can''t tell how he feels.','Some people are calm at school and explode at home, or the other way round.',1),
('responsibility','⚖️','Taking responsibility','Character',6,false,'Blames others','Never learns from what went wrong.','Puts the blame on other people unfairly.','Owns it','Knows that actions and words have results, and accepts them without excuses.','Blames himself for everything','Feels guilty even for things that were not his fault.','Takes over other people''s jobs, so they don''t learn.',null,2),
('empathy','💗','Respect & empathy','Character',6,true,'Selfish','Finds it hard to keep real friends.','Ignores how others feel.','Kind and caring','Treats others kindly and understands their feelings.','People-pleaser','Can''t say no and forgets his own needs.','Others may lean on him too much.',null,3),
('decisions','🧭','Making decisions','Character',7,true,'Can''t decide','Misses chances while waiting.','Others always have to decide for him.','Chooses wisely','Thinks, chooses, and accepts the results of the choice.','Rushes and takes over','Jumps in without thinking about the results.','Decides for others without asking them.',null,4),
('self_honesty','🪞','Honest with myself','Character',7,false,'Denies mistakes','Doesn''t learn from experience.','Others get blamed for his mistakes.','Sees himself clearly','Admits mistakes and is honest with himself.','Too hard on himself','Every mistake feels like a disaster.','Can be just as harsh about other people''s mistakes.',null,5),
('conscience','🌟','Inner compass (conscience)','Character',7,false,'Needs a watcher','Does the right thing only when someone is watching.','Can''t be trusted when alone.','Knows right from wrong','Tells good from bad without anyone checking.','Guilty about everything','Worries for days about tiny mistakes.','Judges other people harshly.',null,6),
('mindset','🌱','Scarcity ⇄ Abundance mindset','Mindset',9,true,'Scarcity','Feels anxious and afraid: there is never enough.','"For me to win, you must lose": doesn''t trust, doesn''t share.','Abundance (win-win)','Believes there is enough good for everyone; shares, trusts, and is happy when others succeed.','Too trusting','May be taken advantage of.','Promises more than can really be given.',null,7),
('outlook','☀️','Hope (optimism)','Mindset',6,false,'Complainer','Sees only problems; the future always looks scary.','Brings everyone''s mood down.','Hopeful and realistic','Expects good things and still sees real problems.','Blind optimist','Ignores real problems until they grow.','Doesn''t take other people''s worries seriously.',null,8),
('encouraging','📣','Encouraging others','Character',6,true,'Puts others down','Ends up with people who avoid him.','Makes others feel small and give up.','Honest encourager','Cheers others on and tells the truth kindly.','Empty praise','People stop believing his words.','Says everything is great, so nobody improves.',null,9),
('drive','🔥','Passion & effort','Character',6,true,'Gives up easily','Leaves things unfinished.','Others have to do his share.','Works hard, rests well','Keeps going and takes healthy breaks.','Never stops','Burns out and gets tired or ill.','Forgets the people around him.',null,10),
('confidence','💪','Self-esteem','Character',7,true,'Feels worthless','Doesn''t try, believing he will fail.','Lets others treat him badly.','Healthy confidence','Knows his strengths and his weak points.','Show-off','Can''t hear advice.','Looks down on others.',null,11),
('truthful','🗣️','Telling the truth','Character',6,true,'Lies','Has to remember every lie; gets caught.','People stop trusting him.','Honest and kind','Tells the truth gently.','Hurtfully blunt','Loses friends.','Says hurtful truths without caring how they land.',null,12),
('humour','😄','Humour','Character',7,true,'Always serious','Misses the fun in life.','Others feel they can''t relax around him.','Kind humour','Jokes that make everyone smile, at the right time.','Mask of funny','Jokes to hide sadness or worry.','Jokes that hurt, or jokes when someone needs him to listen.',null,13)
insert into public.conditions (key, icon, name, kind, min_age, aliases, about, signs, helps, traits, position) values
('bullying','🛑','Bullying','behaviour',6,'{}'::text[],'Hurting someone again and again on purpose, when it is hard for them to defend themselves: hitting, mean words, leaving someone out, or online.',array['Picks on the same person again and again','Laughs when someone is hurt','Gets others to join in']::text[],'Tell a trusted adult. People who watch (bystanders) can help by not laughing and by speaking up.',array['empathy','boundaries']::text[],0),
('lying','🤥','Lying','behaviour',6,'{}'::text[],'Saying things that are not true, often to escape trouble or to look better. Small lies tend to grow into bigger ones.',array['Stories change each time','Blames others','Avoids eye contact or over-explains']::text[],'Being honest early, even about mistakes; adults who stay calm when the truth is told.',array['truthful','self_honesty']::text[],1),
('low_self_esteem','🥀','Low self-esteem','issue',7,array['self-esteem']::text[],'Believing you are not good enough, even when that is not true.',array['"I can''t" before trying','Stops trying after one mistake','Lets others be unkind']::text[],'Small wins, kind people, and noticing your strengths.',array['confidence']::text[],2),
('funny_mask','🎭','Living behind a funny mask','issue',10,array['mask of funny']::text[],'Always joking to hide sadness, fear or loneliness inside. Everyone laughs, so nobody asks how they really are.',array['Turns every serious talk into a joke','Seems happy with everyone, but quiet when alone']::text[],'A friend or adult who asks, "How are you, really?" and listens.',array['humour','feelings']::text[],3),
('autism','🐠','Autism','condition',8,array['autism spectrum','Asperger''s']::text[],'A different way the brain works, from birth. It can make noise, change or social rules hard, and often comes with deep focus on favourite topics. Like a fish out of water in some places, and a great swimmer in others. "Asperger''s" is an older name now included in the autism spectrum.',array['Prefers routines; changes feel upsetting','Finds jokes, hints or eye contact hard','Strong interest in a few topics','Sounds, lights or labels can feel too much']::text[],'Understanding and patience from others; doctors and specialists can diagnose it and give support. It is not something to "fix" or tease.','{}'::text[],4),
('ocd','🔁','OCD (obsessive-compulsive disorder)','condition',12,array['وسواس قهري']::text[],'Unwanted, worrying thoughts keep coming back (obsessions), and the person repeats actions to calm the worry (compulsions), like washing or checking again and again.',array['Repeats an action many times','Very upset if things are not "just right"','Knows the worry doesn''t make sense but can''t stop it']::text[],'Doctors and therapists; it can be treated.',array['conscience']::text[],5),
('ptsd','⚡','PTSD (post-traumatic stress disorder)','condition',13,'{}'::text[],'After something very frightening, the memories keep coming back, with nightmares and always feeling on alert, long after the danger is gone.',array['Nightmares or sudden memories','Avoids places that remind them','Jumps at sudden noises']::text[],'Doctors and therapists; it can be treated, and support from family helps a lot.',array['feelings']::text[],6),
('toxic','☠️','Toxic (poisonous) behaviour','behaviour',13,array['poisoned personality']::text[],'A pattern of behaviour that harms the people around: putting others down, tricking them (manipulation), making them feel guilty, or always being the victim. It is not a medical diagnosis.',array['You feel worse about yourself after time with them','Rules change to suit them','Never says sorry']::text[],'Clear boundaries; talking to someone trusted; sometimes keeping distance.',array['boundaries','empathy','encouraging']::text[],7),
('lucifer_effect','🎭','The Lucifer effect','idea',15,'{}'::text[],'An idea from psychologist Philip Zimbardo: ordinary people can do cruel things when the situation pushes them, for example when they get power over others, wear a uniform or nobody checks them. It came from his Stanford Prison Experiment (1971), which other scientists have since criticised.',array['Following the group or a role instead of the conscience','"I was only doing my job"']::text[],'Knowing the danger helps; so does standing up, even alone, when something is wrong.',array['conscience','boundaries']::text[],8),
('narcissistic','🪞','Narcissistic personality disorder','disorder',16,array['narcissist']::text[],'A long-lasting pattern of needing admiration, feeling more special than others, and having little empathy. Only a doctor can diagnose it; calling someone a "narcissist" in a fight is not a diagnosis.',array['Needs constant praise','Can''t take criticism','Uses people to get what they want']::text[],'Doctors and therapists. People around them may need strong boundaries.',array['empathy','confidence']::text[],9),
('bpd','🌊','Borderline personality disorder (BPD)','disorder',18,array['BPD']::text[],'Very strong feelings that change fast, a deep fear of being left alone, relationships that swing between love and anger, and acting on impulse. Only a doctor can diagnose it, and it can be treated (for example with DBT therapy).',array['Feelings change very quickly','Strong fear of being abandoned','Sees people as all good or all bad']::text[],'Doctors and therapists; patience and clear boundaries from others.',array['feelings','boundaries']::text[],10),
('sadism','🖤','Sadism','disorder',18,array['sadistic']::text[],'Enjoying other people''s pain or humiliation. Psychologists study it as one of the "dark traits" of personality. It is very different from simple anger.',array['Enjoys watching others suffer','Cruelty for fun, not only when angry']::text[],'Professionals; the people hurt need protection and support.',array['empathy','conscience']::text[],11)
insert into public.character_roles (key, icon, name, about, position) values ('wise','🦉','Wise one','Explains what is happening and why, and helps others understand.',0),('doctor','🩺','Doctor','Can recognise signs, give a diagnosis and medical advice.',1),('encourager','📣','Encourager','Keeps others going.',2),('hero','🦸','Hero','The one the story follows.',3),('friend','🤝','Friend','Stands next to the hero.',4),('rival','⚔️','Rival','Wants the same thing, or the opposite.',5),('trouble','🌪️','Trouble-maker','Brings the problem into the story.',6),('helper','🧰','Helper','Helps with skills or things.',7),('family','👪','Family','Parents, brothers, sisters, grandparents.',8),('teacher','🧑‍🏫','Teacher','Teaches and guides.',9) on conflict (key) do update set icon=excluded.icon, name=excluded.name, about=excluded.about, position=excluded.position;
