(md5('char:'||'Rover')::uuid,'Rover','🐶',5,'male','none','hero',0,'A curious family dog who wants to help but sometimes jumps in too fast.','{"drive": 1, "decisions": 1, "boundaries": -1, "empathy": 1}'::jsonb,'{}'::text[]),
