(md5('char:'||'Dr. Salma')::uuid,'Dr. Salma','👩‍⚕️',45,'female','doctorate','doctor',0,'A children''s doctor and psychiatrist. She explains signs kindly and says what help is possible.','{"empathy": 0, "truthful": 0, "boundaries": 0, "feelings": 0}'::jsonb,'{}'::text[]),
(md5('char:'||'Ms. Huda')::uuid,'Ms. Huda','👩‍🏫',34,'female','university','teacher',0,'A class teacher who is fair and firm.','{"boundaries": 0, "encouraging": 0, "responsibility": 0, "feelings": 0}'::jsonb,'{}'::text[]),
(md5('char:'||'Mia')::uuid,'Mia','👧',10,'female','primary','hero',0,'Brave and curious; asks a lot of questions.','{"drive": 1, "outlook": 1, "confidence": 0, "empathy": 0}'::jsonb,'{}'::text[]),
(md5('char:'||'Sami')::uuid,'Sami','👦',9,'male','primary','trouble',6,'Quick with excuses. When something breaks, it''s never his fault.','{"responsibility": -2, "truthful": -1, "self_honesty": -1, "confidence": 1}'::jsonb,array['lying']::text[]),
(md5('char:'||'Noor')::uuid,'Noor','👧',11,'female','primary','friend',0,'Helps everyone and never says no, even when she is tired.','{"empathy": 2, "boundaries": {"all": 1, "friends": 2, "home": 1}, "confidence": -1}'::jsonb,'{}'::text[]),
(md5('char:'||'Omar')::uuid,'Omar','🧒',12,'male','middle','trouble',6,'Big for his age; he picks on smaller children when adults aren''t looking.','{"empathy": -2, "boundaries": -2, "conscience": -1, "confidence": 1}'::jsonb,array['bullying']::text[]),
(md5('char:'||'Layla')::uuid,'Layla','👩',13,'female','middle','friend',0,'Calm at school, but at home she explodes when she''s tired.','{"feelings": {"all": 0, "home": -2, "school": 0}, "empathy": 1}'::jsonb,'{}'::text[]),
(md5('char:'||'Hamza')::uuid,'Hamza','👦',10,'male','primary','rival',0,'Complains about everything: the weather, the food, the game.','{"outlook": -2, "encouraging": -1, "drive": -1}'::jsonb,'{}'::text[]),
(md5('char:'||'Sunny')::uuid,'Sunny','🐤',3,'female','none','encourager',0,'A little bird who always says "You can do it!" and means it.','{"outlook": 1, "encouraging": 0, "empathy": 1}'::jsonb,'{}'::text[]),
(md5('char:'||'Captain Hope')::uuid,'Captain Hope','🦸',30,'male','university','hero',0,'A cheerful hero who sometimes ignores real danger because "it''ll be fine".','{"outlook": 2, "decisions": 1, "confidence": 1}'::jsonb,'{}'::text[]),
(md5('char:'||'Tariq')::uuid,'Tariq','🧑',15,'male','high','friend',10,'The funniest person in class. Nobody knows he is sad at home.','{"humour": 2, "feelings": 1, "confidence": -1}'::jsonb,array['funny_mask']::text[]),
(md5('char:'||'Kareem')::uuid,'Kareem','🧒',11,'male','primary','hero',8,'Knows everything about trains. Loud places and changes of plan are hard for him.','{"drive": 2, "truthful": 1, "boundaries": {"all": 0, "friends": 1}}'::jsonb,array['autism']::text[]),
(md5('char:'||'Aunt Mona')::uuid,'Aunt Mona','👩',40,'female','high','family',0,'Gives advice nobody asked for and opens other people''s letters.','{"boundaries": {"all": -2, "home": -2, "work": 0}, "empathy": 1, "truthful": 1}'::jsonb,'{}'::text[]),
(md5('char:'||'Zaid')::uuid,'Zaid','👨',38,'male','university','family',0,'A dad who keeps his feelings inside; his children can''t tell when he is sad.','{"feelings": 2, "responsibility": 1, "humour": -1}'::jsonb,'{}'::text[]),
(md5('char:'||'Rana')::uuid,'Rana','👧',12,'female','middle','hero',0,'Waits so long to choose that the chance is gone.','{"decisions": -2, "confidence": -1, "conscience": 1}'::jsonb,'{}'::text[]),
(md5('char:'||'Fox the Trickster')::uuid,'Fox the Trickster','🦊',6,'male','none','trouble',0,'Clever and charming; he wins by making others lose.','{"mindset": -2, "truthful": -2, "empathy": -1, "confidence": 1}'::jsonb,'{}'::text[]),
(md5('char:'||'Bear Baba')::uuid,'Bear Baba','🐻',20,'male','none','wise',0,'A slow, gentle bear who shares honey with the whole forest.','{"mindset": 0, "empathy": 0, "outlook": 0, "feelings": 0}'::jsonb,'{}'::text[]),
(md5('char:'||'Dana')::uuid,'Dana','👩',14,'female','high','friend',12,'Checks the door lock ten times and feels terrible if things aren''t "just right".','{"conscience": 2, "self_honesty": 1, "feelings": 1}'::jsonb,array['ocd']::text[]),
(md5('char:'||'Lina')::uuid,'Lina','👧',9,'female','primary','friend',7,'Thinks she is bad at everything, so she doesn''t try.','{"confidence": -2, "drive": -1, "outlook": -1}'::jsonb,array['low_self_esteem']::text[]),
(md5('char:'||'Coach Adel')::uuid,'Coach Adel','🧔',35,'male','university','encourager',0,'A football coach who cheers loudly and tells the truth kindly.','{"encouraging": 0, "drive": 1, "truthful": 0}'::jsonb,'{}'::text[]),
