(md5('char:'||'Rex the Robot')::uuid,'Rex the Robot','🤖',1,'other','none','helper',0,'A robot who says exactly what he thinks, even when it hurts.','{"truthful": 2, "empathy": -1, "humour": -2}'::jsonb,'{}'::text[]),
(md5('char:'||'Fatima')::uuid,'Fatima','👩‍💼',28,'female','university','hero',0,'Works all night and forgets to eat; her team never sees her rest.','{"drive": 2, "boundaries": {"all": 0, "work": -1}, "responsibility": 2}'::jsonb,'{}'::text[]),
(md5('char:'||'Mr. Basil')::uuid,'Mr. Basil','👨‍💼',50,'male','university','trouble',13,'A manager who takes credit for his team''s work and makes them feel small.','{"empathy": -2, "encouraging": -2, "truthful": -1, "confidence": 2}'::jsonb,array['toxic']::text[]),
(md5('char:'||'Captain Faris')::uuid,'Captain Faris','🪖',42,'male','university','hero',13,'A soldier home from war. Fireworks make his heart race; he sleeps badly.','{"feelings": 1, "responsibility": 1, "boundaries": 1}'::jsonb,array['ptsd']::text[]),
(md5('char:'||'Guard Kamal')::uuid,'Guard Kamal','💂',25,'male','high','trouble',15,'A kind young man who changes when he gets a uniform and power over others.','{"conscience": {"all": 0, "work": -2}, "boundaries": {"all": 0, "work": -2}}'::jsonb,array['lucifer_effect']::text[]),
(md5('char:'||'Victor')::uuid,'Victor','🕴️',35,'male','university','rival',16,'Charming at first; he needs everyone to admire him and can''t stand criticism.','{"confidence": 2, "empathy": -2, "self_honesty": -2}'::jsonb,array['narcissistic']::text[]),
(md5('char:'||'Rania')::uuid,'Rania','👩',24,'female','university','hero',18,'Loves deeply, fears being left, and her feelings change like the sea.','{"feelings": -2, "boundaries": -1, "decisions": 1}'::jsonb,array['bpd']::text[]),
